mapper.select:
SELECT request_id, tenant_id, source_system, source_event_key,
        notification_template_id, default_locale, default_parameters, notification_route_id, create_time, update_time
        FROM t_notification_request WHERE request_id = #{id}

SELECT request_id, tenant_id, source_system, source_event_key,
        notification_template_id, default_locale, default_parameters, notification_route_id, create_time, update_time
        FROM t_notification_request WHERE source_system = #{sourceSystem} AND source_event_key = #{sourceEventKey}

mapper.sql:
WHERE r.create_time >= #{filter.createdFrom} AND r.create_time < #{filter.createdTo}
AND r.source_system = #{filter.sourceSystem}
AND r.source_event_key = #{filter.sourceEventKey}
AND r.notification_template_id = #{filter.templateId}
AND EXISTS (SELECT 1 FROM t_notification_delivery d
    WHERE d.request_id = r.request_id AND d.status = #{filter.deliveryStatus})
